True from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row if value != 0)
    color = min(counts, key=counts.get)
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == color]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = {(r - r0, c - c0) for r, c in points}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h - sh + 1):
        for c in range(w - sw + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r + dr][c + dc] = color
    return out
